<?php require '../includes/db.php';require '../includes/functions.php';login_required();$uid=(int)$_SESSION['user_id'];$s=$conn->prepare('SELECT id,total,status,created_at FROM orders WHERE user_id=? ORDER BY created_at DESC');$s->bind_param('i',$uid);$s->execute();$rows=$s->get_result();$page_title='My Orders';include '../includes/header.php';?><h1>Order History</h1><table><tr><th>Order</th><th>Date</th><th>Total</th><th>Status</th><th>Invoice</th></tr><?php while($x=$rows->fetch_assoc()):?><tr><td>#<?=$x['id']?></td><td><?=e($x['created_at'])?></td><td><?=cash($x['total'])?></td><td><?=e($x['status'])?></td><td><a href="invoice.php?id=<?=$x['id']?>">View</a></td></tr><?php endwhile;?></table><?php include '../includes/footer.php';?>
